// first index with a[idx] >= x  (search space [lo, hi))
int lo = 0, hi = n;
while(lo < hi){
  int mid = lo + (hi - lo) / 2;
  if(a[mid] < x) lo = mid + 1; else hi = mid;
}
// lo is the answer (n if all elements < x)

int lo = 0, hi = n - 1;
while(lo <= hi){
  int mid = lo + (hi - lo) / 2;
  if(a[mid] == t) return mid;
  if(a[lo] <= a[mid]){ // left sorted
    if(a[lo] <= t && t < a[mid]) hi = mid - 1; else lo = mid + 1;
  } else {             // right sorted
    if(a[mid] < t && t <= a[hi]) lo = mid + 1; else hi = mid - 1;
  }
}

