// maximum X such that ok(X) is true
while(lo < hi){
  int mid = lo + (hi - lo + 1) / 2;
  if(ok(mid)) lo = mid; else hi = mid - 1;
}

int lo = 0, hi = R * C - 1;
while(lo <= hi){
  int mid = lo + (hi - lo) / 2;
  int v = m[mid / C][mid % C];
  if(v == t) return true;
  if(v < t) lo = mid + 1; else hi = mid - 1;
}

int lo = 1, hi = n - 1;      // value range
while(lo < hi){
  int mid = lo + (hi - lo) / 2;
  int cnt = 0;
  for(int x : a) if(x <= mid) cnt++;
  if(cnt > mid) hi = mid; else lo = mid + 1;
}
